import {FIELD,ZONES} from './data.js';
export function upgradeParticipation(s,now=Date.now()){
 let changed=false;
 for(const p of Object.values(s.profiles))if(!Number.isInteger(p.courtPosition)){const b=Object.values(s.bookings).find(b=>b.personId===p.id&&FIELD.includes(b.slot)&&b.status==='confirmed');p.courtPosition=b?ZONES[b.slot]:1;changed=true;}
 for(const g of Object.values(s.groups))if(g.logo===undefined){g.logo=['bg-voltaren','bg-smash','bg-bagher','bg-volley-spritz','bs-friends','bs-leonessa'].includes(g.id)?'assets/groups/'+g.id+'.svg':null;changed=true;}
 for(const m of Object.values(s.matches))if(m.status==='active'&&Date.parse(m.startsAt)>now&&!m.organizerAssigned){const g=s.groups[m.groupId];if(!g||g.deletedAt)continue;const bookings=Object.values(s.bookings).filter(b=>b.matchId===m.id&&(b.status==='confirmed'||b.status==='pending'&&s.requests[b.requestId]?.status==='pending'&&Date.parse(s.requests[b.requestId].expiresAt)>now)),own=bookings.find(b=>b.personId===g.ownerId);if(own){if(own.status==='pending'){own.status='confirmed';const r=s.requests[own.requestId];if(r){r.status='accepted';r.decidedBy=g.ownerId;r.decidedAt=new Date(now).toISOString();}own.requestId=null;}m.organizerAssigned=true;changed=true;continue;}const position=s.profiles[g.ownerId]?.courtPosition||1,slot=FIELD.find(slot=>ZONES[slot]===position&&!bookings.some(b=>b.slot===slot));if(!slot||bookings.length>=m.capacity){if(m.organizerIssue!=='organizerNoSeat'){m.organizerIssue='organizerNoSeat';changed=true;}continue;}const bid='booking-'+(++s.seq);s.bookings[bid]={id:bid,personId:g.ownerId,matchId:m.id,slot,status:'confirmed',requestId:null,createdAt:new Date(now).toISOString(),priceCents:m.priceCents,paymentStatus:'unpaid',automaticOrganizer:true};m.organizerAssigned=true;delete m.organizerIssue;changed=true;}
 for(const b of Object.values(s.bookings)){const m=s.matches[b.matchId],g=m&&s.groups[m.groupId];if(m?.status==='active'&&Date.parse(m.startsAt)>now&&g?.ownerId===b.personId&&b.status==='confirmed'&&b.paymentStatus==='unpaid'){b.originalPriceCents=b.priceCents;b.priceCents=0;b.paymentStatus='exempt';changed=true;}}return changed;
}
